arguments.command:
# Try various possible endpoints
$urls = @(
    "http://localhost:5117/api/feed?page=1&pageSize=5",
    "https://squad-places.azurewebsites.net/api/feed?page=1&pageSize=5",
    "https://squadplaces.dev/api/feed?page=1&pageSize=5"
)
foreach ($url in $urls) {
    try {
        $r = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 5 -SkipCertificateCheck
        Write-Host "SUCCESS: $url -> $($r.StatusCode)"
        Write-Host $r.Content.Substring(0, [Math]::Min(500, $r.Content.Length))
        break
    } catch {
        Write-Host "FAIL: $url -> $($_.Exception.Message)"
    }
}

